HTML_CONTENT = '<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>CourseMate — Course Q&A & Notes (MongoDB Atlas RAG)</title>\n  <script src="https://cdn.tailwindcss.com"></script>\n  <link rel="preconnect" href="https://fonts.googleapis.com">\n  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">\n  <style>\n    body { font-family: \'Inter\', sans-serif; }\n    .tab-active { border-color: #3b82f6; color: #1d4ed8; background-color: #eff6ff; }\n  </style>\n</head>\n<body class="bg-slate-50 text-slate-800 min-h-screen flex flex-col">\n\n  <!-- Top Navbar -->\n  <header class="bg-white border-b border-slate-200 sticky top-0 z-30">\n    <div class="max-w-6xl mx-auto px-4 h-16 flex items-center justify-between">\n      <div class="flex items-center gap-3">\n        <div class="w-10 h-10 rounded-xl bg-gradient-to-tr from-blue-600 to-indigo-500 flex items-center justify-center text-white font-bold text-xl shadow-sm">\n          CM\n        </div>\n        <div>\n          <h1 class="font-bold text-lg text-slate-900 leading-tight">CourseMate</h1>\n          <p class="text-xs text-slate-500">Course Q&A & Notes Service · MongoDB Atlas RAG</p>\n        </div>\n      </div>\n      <div class="flex items-center gap-3">\n        <span id="health-pill" class="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-medium bg-amber-50 text-amber-700 border border-amber-200">\n          <span class="w-2 h-2 rounded-full bg-amber-400 animate-pulse"></span> Connecting DB...\n        </span>\n        <a href="/docs" target="_blank" class="text-xs font-medium px-3 py-1.5 rounded-lg border border-slate-200 hover:bg-slate-50 text-slate-700 transition">\n          Swagger API ↗\n        </a>\n      </div>\n    </div>\n  </header>\n\n  <!-- Navigation Tabs -->\n  <div class="bg-white border-b border-slate-200">\n    <div class="max-w-6xl mx-auto px-4 flex gap-2">\n      <button onclick="switchTab(\'qa\')" id="tab-btn-qa" class="px-4 py-3 font-medium text-sm border-b-2 border-transparent text-slate-600 hover:text-slate-900 transition flex items-center gap-2 tab-active">\n        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z"></path></svg>\n        Course Q&A (RAG)\n      </button>\n      <button onclick="switchTab(\'docs\')" id="tab-btn-docs" class="px-4 py-3 font-medium text-sm border-b-2 border-transparent text-slate-600 hover:text-slate-900 transition flex items-center gap-2">\n        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253"></path></svg>\n        Course Materials\n      </button>\n      <button onclick="switchTab(\'analytics\')" id="tab-btn-analytics" class="px-4 py-3 font-medium text-sm border-b-2 border-transparent text-slate-600 hover:text-slate-900 transition flex items-center gap-2">\n        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"></path></svg>\n        Aggregation Analytics\n      </button>\n      <button onclick="switchTab(\'architecture\')" id="tab-btn-architecture" class="px-4 py-3 font-medium text-sm border-b-2 border-transparent text-slate-600 hover:text-slate-900 transition flex items-center gap-2">\n        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"></path></svg>\n        System Architecture\n      </button>\n    </div>\n  </div>\n\n  <!-- Main Container -->\n  <main class="max-w-6xl mx-auto px-4 py-8 flex-1 w-full">\n\n    <!-- TAB 1: Q&A -->\n    <div id="tab-qa" class="space-y-6">\n      <div class="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm">\n        <h2 class="text-xl font-bold text-slate-900 mb-2">Ask Course Materials</h2>\n        <p class="text-sm text-slate-600 mb-5">Questions are retrieved from document chunks in MongoDB using Atlas Vector Search or cosine similarity, and cited with sources.</p>\n\n        <form id="ask-form" onsubmit="handleAsk(event)" class="space-y-4">\n          <div class="grid grid-cols-1 md:grid-cols-4 gap-4">\n            <div class="md:col-span-1">\n              <label class="block text-xs font-semibold text-slate-700 uppercase tracking-wider mb-1.5">Filter by Course</label>\n              <select id="course-select" class="w-full bg-slate-50 border border-slate-300 text-slate-800 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500">\n                <option value="">All Courses</option>\n              </select>\n            </div>\n            <div class="md:col-span-3">\n              <label class="block text-xs font-semibold text-slate-700 uppercase tracking-wider mb-1.5">Question</label>\n              <div class="flex gap-2">\n                <input type="text" id="question-input" required placeholder="e.g. How does a B-Tree index speed up equality lookups and range scans?" class="flex-1 bg-slate-50 border border-slate-300 text-slate-900 rounded-xl px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500">\n                <button type="submit" id="ask-btn" class="bg-blue-600 hover:bg-blue-700 text-white font-medium px-6 py-2.5 rounded-xl text-sm transition flex items-center gap-2 shadow-sm">\n                  <span>Ask</span>\n                </button>\n              </div>\n            </div>\n          </div>\n        </form>\n\n        <!-- Quick prompts -->\n        <div class="mt-4 flex flex-wrap items-center gap-2">\n          <span class="text-xs font-medium text-slate-500">Try asking:</span>\n          <button onclick="setQuery(\'How does a B-Tree index speed up lookups?\')" class="text-xs bg-slate-100 hover:bg-slate-200 text-slate-700 px-2.5 py-1 rounded-lg transition">B-Tree lookups</button>\n          <button onclick="setQuery(\'What is the leftmost prefix rule in composite indexes?\')" class="text-xs bg-slate-100 hover:bg-slate-200 text-slate-700 px-2.5 py-1 rounded-lg transition">Leftmost prefix rule</button>\n          <button onclick="setQuery(\'How does two-phase commit ensure atomicity in distributed transactions?\')" class="text-xs bg-slate-100 hover:bg-slate-200 text-slate-700 px-2.5 py-1 rounded-lg transition">Two-phase commit</button>\n          <button onclick="setQuery(\'Why do replica sets require an odd number of voting nodes?\')" class="text-xs bg-slate-100 hover:bg-slate-200 text-slate-700 px-2.5 py-1 rounded-lg transition">Replica set quorum</button>\n        </div>\n      </div>\n\n      <!-- Result Card -->\n      <div id="answer-container" class="hidden bg-white rounded-2xl border border-slate-200 p-6 shadow-sm space-y-5">\n        <div class="flex flex-wrap items-center justify-between gap-3 pb-4 border-b border-slate-100">\n          <div class="flex items-center gap-2">\n            <span class="text-xs font-semibold uppercase tracking-wider text-slate-500">Answer</span>\n            <span id="badge-retrieval" class="text-xs px-2.5 py-0.5 rounded-full font-medium bg-blue-50 text-blue-700 border border-blue-200">Retrieval</span>\n            <span id="badge-mode" class="text-xs px-2.5 py-0.5 rounded-full font-medium bg-emerald-50 text-emerald-700 border border-emerald-200">Mode</span>\n          </div>\n          <div class="text-xs text-slate-500 font-mono" id="answer-latency">Latency: -- ms</div>\n        </div>\n\n        <div id="answer-text" class="text-slate-800 text-sm leading-relaxed whitespace-pre-line bg-slate-50 p-4 rounded-xl border border-slate-100">\n        </div>\n\n        <div>\n          <h3 class="text-xs font-semibold uppercase tracking-wider text-slate-500 mb-3">Cited Sources & Chunks</h3>\n          <div id="sources-list" class="space-y-2">\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <!-- TAB 2: Materials & Courses -->\n    <div id="tab-docs" class="hidden space-y-6">\n      <div class="grid grid-cols-1 md:grid-cols-3 gap-6">\n        <!-- New Course Form -->\n        <div class="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm space-y-4">\n          <h2 class="text-lg font-bold text-slate-900">Add Course</h2>\n          <form onsubmit="handleCreateCourse(event)" class="space-y-3">\n            <div>\n              <label class="block text-xs font-medium text-slate-700 mb-1">Course Code</label>\n              <input type="text" id="new-course-code" required placeholder="e.g. CS F212" class="w-full bg-slate-50 border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:outline-none">\n            </div>\n            <div>\n              <label class="block text-xs font-medium text-slate-700 mb-1">Course Name</label>\n              <input type="text" id="new-course-name" required placeholder="e.g. Database Systems" class="w-full bg-slate-50 border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:outline-none">\n            </div>\n            <button type="submit" class="w-full bg-slate-900 hover:bg-slate-800 text-white font-medium py-2 rounded-lg text-sm transition">Create Course</button>\n          </form>\n        </div>\n\n        <!-- Ingest Document Form -->\n        <div class="md:col-span-2 bg-white rounded-2xl border border-slate-200 p-6 shadow-sm space-y-4">\n          <h2 class="text-lg font-bold text-slate-900">Upload Course Material</h2>\n          <form onsubmit="handleIngestDoc(event)" class="space-y-3">\n            <div class="grid grid-cols-1 md:grid-cols-2 gap-3">\n              <div>\n                <label class="block text-xs font-medium text-slate-700 mb-1">Course</label>\n                <select id="doc-course-select" required class="w-full bg-slate-50 border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:outline-none"></select>\n              </div>\n              <div>\n                <label class="block text-xs font-medium text-slate-700 mb-1">Document Title</label>\n                <input type="text" id="doc-title" required placeholder="e.g. Lecture 4: Indexing and B-Trees" class="w-full bg-slate-50 border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:outline-none">\n              </div>\n            </div>\n            <div>\n              <label class="block text-xs font-medium text-slate-700 mb-1">Material Content (Auto-chunked & Embedded)</label>\n              <textarea id="doc-text" rows="5" required placeholder="Paste handbook chapters, lecture notes, or FAQs here..." class="w-full bg-slate-50 border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:outline-none font-sans"></textarea>\n            </div>\n            <button type="submit" id="ingest-btn" class="bg-blue-600 hover:bg-blue-700 text-white font-medium px-5 py-2 rounded-lg text-sm transition">Chunk & Ingest into MongoDB</button>\n          </form>\n        </div>\n      </div>\n\n      <!-- Current Courses Table -->\n      <div class="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm space-y-4">\n        <h2 class="text-lg font-bold text-slate-900">Registered Courses</h2>\n        <div class="overflow-x-auto">\n          <table class="w-full text-left text-sm">\n            <thead class="bg-slate-50 border-b border-slate-200 text-xs font-semibold text-slate-500 uppercase tracking-wider">\n              <tr>\n                <th class="px-4 py-3">Code</th>\n                <th class="px-4 py-3">Course Name</th>\n                <th class="px-4 py-3">Course ID</th>\n                <th class="px-4 py-3 text-right">Actions</th>\n              </tr>\n            </thead>\n            <tbody id="courses-tbody" class="divide-y divide-slate-100">\n              <tr><td colspan="4" class="px-4 py-4 text-center text-slate-400">Loading courses...</td></tr>\n            </tbody>\n          </table>\n        </div>\n      </div>\n    </div>\n\n    <!-- TAB 3: Analytics -->\n    <div id="tab-analytics" class="hidden space-y-6">\n      <div class="grid grid-cols-1 md:grid-cols-3 gap-6">\n        <div class="bg-white rounded-2xl border border-slate-200 p-5 shadow-sm">\n          <p class="text-xs font-semibold text-slate-500 uppercase tracking-wider">Total Questions Logged</p>\n          <p id="stat-total-queries" class="text-3xl font-extrabold text-blue-600 mt-2">--</p>\n          <p class="text-xs text-slate-500 mt-1">Logged in <code class="bg-slate-100 px-1 py-0.5 rounded">query_logs</code> collection</p>\n        </div>\n        <div class="bg-white rounded-2xl border border-slate-200 p-5 shadow-sm">\n          <p class="text-xs font-semibold text-slate-500 uppercase tracking-wider">Top Cited Document</p>\n          <p id="stat-top-doc" class="text-lg font-bold text-slate-900 mt-2 truncate">--</p>\n          <p class="text-xs text-slate-500 mt-1" id="stat-top-doc-count">0 citations</p>\n        </div>\n        <div class="bg-white rounded-2xl border border-slate-200 p-5 shadow-sm">\n          <p class="text-xs font-semibold text-slate-500 uppercase tracking-wider">Replica Status</p>\n          <p id="stat-primary" class="text-lg font-bold text-emerald-600 mt-2 truncate">Primary</p>\n          <p class="text-xs text-slate-500 mt-1">Local or Atlas replica cluster</p>\n        </div>\n      </div>\n\n      <div class="grid grid-cols-1 md:grid-cols-2 gap-6">\n        <!-- Queries Per Day -->\n        <div class="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm space-y-4">\n          <h3 class="font-bold text-slate-900 text-sm uppercase tracking-wider">Daily Query Volume ($dateToString)</h3>\n          <div class="overflow-x-auto">\n            <table class="w-full text-left text-sm">\n              <thead class="bg-slate-50 text-xs font-semibold text-slate-500 uppercase">\n                <tr><th class="px-4 py-2">Date</th><th class="px-4 py-2 text-right">Queries</th></tr>\n              </thead>\n              <tbody id="analytics-per-day" class="divide-y divide-slate-100"></tbody>\n            </table>\n          </div>\n        </div>\n\n        <!-- Top Cited Documents -->\n        <div class="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm space-y-4">\n          <h3 class="font-bold text-slate-900 text-sm uppercase tracking-wider">Top Documents Cited ($unwind + $group)</h3>\n          <div class="overflow-x-auto">\n            <table class="w-full text-left text-sm">\n              <thead class="bg-slate-50 text-xs font-semibold text-slate-500 uppercase">\n                <tr><th class="px-4 py-2">Document Title</th><th class="px-4 py-2 text-right">Times Retrieved</th></tr>\n              </thead>\n              <tbody id="analytics-top-docs" class="divide-y divide-slate-100"></tbody>\n            </table>\n          </div>\n        </div>\n      </div>\n\n      <!-- Course Stats -->\n      <div class="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm space-y-4">\n        <h3 class="font-bold text-slate-900 text-sm uppercase tracking-wider">Course Retrieval Performance ($lookup + $avg)</h3>\n        <div class="overflow-x-auto">\n          <table class="w-full text-left text-sm">\n            <thead class="bg-slate-50 text-xs font-semibold text-slate-500 uppercase">\n              <tr>\n                <th class="px-4 py-2">Course Code</th>\n                <th class="px-4 py-2 text-right">Queries</th>\n                <th class="px-4 py-2 text-right">Avg Top Score</th>\n                <th class="px-4 py-2 text-right">Avg Latency (ms)</th>\n              </tr>\n            </thead>\n            <tbody id="analytics-courses" class="divide-y divide-slate-100"></tbody>\n          </table>\n        </div>\n      </div>\n    </div>\n\n    <!-- TAB 4: Architecture -->\n    <div id="tab-architecture" class="hidden space-y-6">\n      <div class="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm space-y-4">\n        <h2 class="text-xl font-bold text-slate-900">CourseMate Architecture & Design Notes</h2>\n        <p class="text-sm text-slate-600">Built to demonstrate production MongoDB design patterns in system design interviews:</p>\n\n        <div class="grid grid-cols-1 md:grid-cols-2 gap-4 mt-4">\n          <div class="border border-slate-200 rounded-xl p-4 bg-slate-50">\n            <h4 class="font-bold text-sm text-slate-900 mb-1">1. Schema Design: Embedding vs. Referencing</h4>\n            <p class="text-xs text-slate-600 leading-relaxed">\n              <strong>Embed</strong> small, bounded data with 1:1 or 1:few cardinality (tags, metadata, audit timestamps).<br>\n              <strong>Reference</strong> large, unbounded data: <code>chunks</code> reference <code>documents</code> via <code>doc_id</code>, avoiding MongoDB\'s 16MB BSON document limit.\n            </p>\n          </div>\n          <div class="border border-slate-200 rounded-xl p-4 bg-slate-50">\n            <h4 class="font-bold text-sm text-slate-900 mb-1">2. Indexes & ESR Rule</h4>\n            <p class="text-xs text-slate-600 leading-relaxed">\n              Compound index on <code>(course_id, created_at)</code> follows the Equality-Sort-Range rule.<br>\n              Text index on document titles for keyword discovery, unique index on <code>email</code> and course <code>code</code>.\n            </p>\n          </div>\n          <div class="border border-slate-200 rounded-xl p-4 bg-slate-50">\n            <h4 class="font-bold text-sm text-slate-900 mb-1">3. Atlas Vector Search ($vectorSearch)</h4>\n            <p class="text-xs text-slate-600 leading-relaxed">\n              Hierarchical Navigable Small World (HNSW) index on 384-dim embeddings. Falls back to brute-force cosine similarity if run on local standalone MongoDB.\n            </p>\n          </div>\n          <div class="border border-slate-200 rounded-xl p-4 bg-slate-50">\n            <h4 class="font-bold text-sm text-slate-900 mb-1">4. Replication & Failover</h4>\n            <p class="text-xs text-slate-600 leading-relaxed">\n              Local 3-node replica set (<code>rs0</code>) with automatic Raft-like election when primary dies. In Atlas M0, a multi-AZ replica set runs underneath automatically.\n            </p>\n          </div>\n        </div>\n      </div>\n    </div>\n\n  </main>\n\n  <footer class="bg-white border-t border-slate-200 py-4 text-center text-xs text-slate-500">\n    CourseMate &middot; MongoDB Atlas RAG &middot; FastAPI Backend\n  </footer>\n\n  <script>\n    let courses = [];\n\n    // Safe JSON fetch — always returns {ok, data, error, status}\n    async function safeFetch(url, options = {}) {\n      try {\n        const res = await fetch(url, options);\n        const text = await res.text();\n        let data;\n        try { data = JSON.parse(text); } catch { data = { detail: text }; }\n        return { ok: res.ok, status: res.status, data };\n      } catch (e) {\n        return { ok: false, status: 0, data: { detail: String(e) } };\n      }\n    }\n\n    async function loadHealth() {\n      const { ok, data } = await safeFetch(\'/health\');\n      const pill = document.getElementById(\'health-pill\');\n      if (data && data.ok) {\n        pill.className = "inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-medium bg-emerald-50 text-emerald-700 border border-emerald-200";\n        pill.innerHTML = `<span class="w-2 h-2 rounded-full bg-emerald-500"></span> Primary: ${data.primary || \'Standalone\'}`;\n        document.getElementById(\'stat-primary\').innerText = data.primary || \'Standalone\';\n      } else {\n        const msg = data?.error || data?.detail || \'DB Offline\';\n        pill.className = "inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-medium bg-rose-50 text-rose-700 border border-rose-200";\n        pill.innerHTML = `<span class="w-2 h-2 rounded-full bg-rose-500"></span> DB Offline`;\n        pill.title = msg;\n        console.error(\'Health error:\', msg, data?.uri);\n      }\n    }\n\n    async function loadCourses() {\n      try {\n        const { ok, data } = await safeFetch(\'/courses\');\n        courses = ok && Array.isArray(data) ? data : [];\n        \n        // Populate dropdowns\n        const filterSel = document.getElementById(\'course-select\');\n        const docSel = document.getElementById(\'doc-course-select\');\n        \n        filterSel.innerHTML = \'<option value="">All Courses</option>\';\n        docSel.innerHTML = \'<option value="" disabled selected>Select a course</option>\';\n        \n        courses.forEach(c => {\n          filterSel.innerHTML += `<option value="${c.id}">${c.code} — ${c.name}</option>`;\n          docSel.innerHTML += `<option value="${c.id}">${c.code} — ${c.name}</option>`;\n        });\n\n        // Populate table\n        const tbody = document.getElementById(\'courses-tbody\');\n        if (courses.length === 0) {\n          tbody.innerHTML = \'<tr><td colspan="4" class="px-4 py-4 text-center text-slate-400">No courses yet. Add one above!</td></tr>\';\n        } else {\n          tbody.innerHTML = courses.map(c => `\n            <tr class="hover:bg-slate-50">\n              <td class="px-4 py-3 font-semibold text-slate-900">${c.code}</td>\n              <td class="px-4 py-3 text-slate-700">${c.name}</td>\n              <td class="px-4 py-3 font-mono text-xs text-slate-500">${c.id}</td>\n              <td class="px-4 py-3 text-right">\n                <button onclick="deleteCourse(\'${c.id}\')" class="text-xs text-rose-600 hover:text-rose-800 font-medium">Delete</button>\n              </td>\n            </tr>\n          `).join(\'\');\n        }\n      } catch (e) {\n        console.error(e);\n      }\n    }\n\n    async function handleAsk(e) {\n      e.preventDefault();\n      const question = document.getElementById(\'question-input\').value.trim();\n      const courseId = document.getElementById(\'course-select\').value || null;\n      const btn = document.getElementById(\'ask-btn\');\n\n      btn.disabled = true;\n      btn.innerHTML = `<span>Searching...</span>`;\n\n      try {\n        const { ok, data } = await safeFetch(\'/ask\', {\n          method: \'POST\',\n          headers: { \'Content-Type\': \'application/json\' },\n          body: JSON.stringify({ question, course_id: courseId })\n        });\n\n        const container = document.getElementById(\'answer-container\');\n        container.classList.remove(\'hidden\');\n\n        if (!ok) {\n          document.getElementById(\'answer-text\').innerText = `Error: ${data.detail || \'Server error\'}`;\n          document.getElementById(\'badge-retrieval\').innerText = \'error\';\n          document.getElementById(\'badge-mode\').innerText = \'error\';\n          document.getElementById(\'answer-latency\').innerText = \'\';\n          document.getElementById(\'sources-list\').innerHTML = \'\';\n          return;\n        }\n\n        document.getElementById(\'answer-text\').innerText = data.answer;\n        document.getElementById(\'badge-retrieval\').innerText = data.retrieval_mode;\n        document.getElementById(\'badge-mode\').innerText = data.answer_mode;\n        document.getElementById(\'answer-latency\').innerText = `Latency: ${data.latency_ms} ms`;\n\n        const sourcesList = document.getElementById(\'sources-list\');\n        if (!data.sources || data.sources.length === 0) {\n          sourcesList.innerHTML = \'<p class="text-xs text-slate-400">No sources retrieved.</p>\';\n        } else {\n          sourcesList.innerHTML = data.sources.map(s => `\n            <div class="border border-slate-200 rounded-xl p-3 bg-white hover:border-blue-300 transition">\n              <div class="flex items-center justify-between text-xs mb-1">\n                <span class="font-semibold text-slate-800">[${s.n}] ${s.title} (Chunk #${s.chunk_idx})</span>\n                <span class="bg-blue-50 text-blue-700 px-2 py-0.5 rounded font-mono">Score: ${s.score}</span>\n              </div>\n              <p class="text-xs text-slate-600 font-mono bg-slate-50 p-2 rounded">${s.snippet}...</p>\n            </div>\n          `).join(\'\');\n        }\n      } catch (err) {\n        alert("Failed to ask question: " + err);\n      } finally {\n        btn.disabled = false;\n        btn.innerHTML = `<span>Ask</span>`;\n      }\n    }\n\n    async function handleCreateCourse(e) {\n      e.preventDefault();\n      const code = document.getElementById(\'new-course-code\').value.trim();\n      const name = document.getElementById(\'new-course-name\').value.trim();\n      try {\n        const res = await fetch(\'/courses\', {\n          method: \'POST\',\n          headers: { \'Content-Type\': \'application/json\' },\n          body: JSON.stringify({ code, name })\n        });\n        if (!res.ok) {\n          const err = await res.json();\n          alert(err.detail || "Error creating course");\n          return;\n        }\n        document.getElementById(\'new-course-code\').value = \'\';\n        document.getElementById(\'new-course-name\').value = \'\';\n        await loadCourses();\n      } catch (err) {\n        alert("Error: " + err);\n      }\n    }\n\n    async function deleteCourse(id) {\n      if (!confirm("Are you sure you want to delete this course?")) return;\n      try {\n        await fetch(`/courses/${id}`, { method: \'DELETE\' });\n        await loadCourses();\n      } catch (err) {\n        alert("Error: " + err);\n      }\n    }\n\n    async function handleIngestDoc(e) {\n      e.preventDefault();\n      const course_id = document.getElementById(\'doc-course-select\').value;\n      const title = document.getElementById(\'doc-title\').value.trim();\n      const text = document.getElementById(\'doc-text\').value.trim();\n      const btn = document.getElementById(\'ingest-btn\');\n\n      btn.disabled = true;\n      btn.innerText = "Chunking & Embedding...";\n\n      try {\n        const res = await fetch(\'/documents\', {\n          method: \'POST\',\n          headers: { \'Content-Type\': \'application/json\' },\n          body: JSON.stringify({ course_id, title, text })\n        });\n        const data = await res.json();\n        alert(`Document ingested successfully! Created ${data.chunk_count} vector chunks.`);\n        document.getElementById(\'doc-title\').value = \'\';\n        document.getElementById(\'doc-text\').value = \'\';\n      } catch (err) {\n        alert("Ingestion error: " + err);\n      } finally {\n        btn.disabled = false;\n        btn.innerText = "Chunk & Ingest into MongoDB";\n      }\n    }\n\n    async function loadAnalytics() {\n      try {\n        const [perDay, topDocs, courseStats] = await Promise.all([\n          fetch(\'/analytics/queries-per-day\').then(r => r.json()),\n          fetch(\'/analytics/top-documents\').then(r => r.json()),\n          fetch(\'/analytics/course-stats\').then(r => r.json())\n        ]);\n\n        // Per Day\n        const perDayTbody = document.getElementById(\'analytics-per-day\');\n        let totalQueries = 0;\n        if (perDay.length === 0) {\n          perDayTbody.innerHTML = \'<tr><td colspan="2" class="px-4 py-2 text-slate-400">No query logs yet.</td></tr>\';\n        } else {\n          perDayTbody.innerHTML = perDay.map(d => {\n            totalQueries += d.queries;\n            return `<tr><td class="px-4 py-2 font-mono text-xs">${d.day}</td><td class="px-4 py-2 text-right font-semibold">${d.queries}</td></tr>`;\n          }).join(\'\');\n        }\n        document.getElementById(\'stat-total-queries\').innerText = totalQueries;\n\n        // Top Docs\n        const topDocsTbody = document.getElementById(\'analytics-top-docs\');\n        if (topDocs.length === 0) {\n          topDocsTbody.innerHTML = \'<tr><td colspan="2" class="px-4 py-2 text-slate-400">No citations yet.</td></tr>\';\n        } else {\n          document.getElementById(\'stat-top-doc\').innerText = topDocs[0].title;\n          document.getElementById(\'stat-top-doc-count\').innerText = `${topDocs[0].times_retrieved} citations`;\n          topDocsTbody.innerHTML = topDocs.map(d => `\n            <tr><td class="px-4 py-2 font-medium">${d.title}</td><td class="px-4 py-2 text-right font-semibold text-blue-600">${d.times_retrieved}</td></tr>\n          `).join(\'\');\n        }\n\n        // Course Stats\n        const courseTbody = document.getElementById(\'analytics-courses\');\n        if (courseStats.length === 0) {\n          courseTbody.innerHTML = \'<tr><td colspan="4" class="px-4 py-2 text-slate-400">No course statistics yet.</td></tr>\';\n        } else {\n          courseTbody.innerHTML = courseStats.map(c => `\n            <tr>\n              <td class="px-4 py-2 font-semibold text-slate-900">${c.course_code}</td>\n              <td class="px-4 py-2 text-right">${c.queries}</td>\n              <td class="px-4 py-2 text-right font-mono text-xs">${c.avg_top_score}</td>\n              <td class="px-4 py-2 text-right font-mono text-xs">${c.avg_latency_ms} ms</td>\n            </tr>\n          `).join(\'\');\n        }\n      } catch (e) {\n        console.error("Analytics error:", e);\n      }\n    }\n\n    function setQuery(q) {\n      document.getElementById(\'question-input\').value = q;\n      document.getElementById(\'ask-form\').dispatchEvent(new Event(\'submit\'));\n    }\n\n    function switchTab(tab) {\n      [\'qa\', \'docs\', \'analytics\', \'architecture\'].forEach(t => {\n        document.getElementById(`tab-${t}`).classList.add(\'hidden\');\n        document.getElementById(`tab-btn-${t}`).classList.remove(\'tab-active\');\n      });\n      document.getElementById(`tab-${tab}`).classList.remove(\'hidden\');\n      document.getElementById(`tab-btn-${tab}`).classList.add(\'tab-active\');\n\n      if (tab === \'analytics\') loadAnalytics();\n      if (tab === \'docs\') loadCourses();\n    }\n\n    // Init\n    loadHealth();\n    loadCourses();\n  </script>\n</body>\n</html>\n'
